  Lemma kimg_rdn_n : forall E M kn (a : Z) (n : nat) bs,
    know_ok RSEGS E M kn -> existsb (is_kimg_cov a (Z.of_nat n)) kn = true ->
    rdn RSEGS (fun _ => None) (Z_to_bv 64 a) n = Some bs -> (0 <= a)%Z -> (a + Z.of_nat n < 2 ^ 64)%Z ->
